    const scan = (label, p) => {
        for (const m of p.matchAll(/font-size: ?([\d.]+)px/g)) assert.ok(FS.includes(m[1]), label + ' に物差しの外の文字 ' + m[1] + 'px');
        for (const m of p.matchAll(/border-radius: ?([\d.]+)px/g)) assert.ok(RAD.includes(m[1]), label + ' に物差しの外の角丸 ' + m[1] + 'px');
    };
