        assert.ok(/const r = isTest\s*\n\s*\? await window\.supabaseQuickCreateTestSeason\(\{ bosses, hardDate, monthKey \}\)\s*\n\s*: await window\.supabaseCreateSeason\(/.test(html), '作成シートの 🧪 がリハーサルの口を通らない');
