        assert.ok(fn.includes("handleOpsFinishOpt('shots'") && !fn.includes("handleOpsFinishOpt('hours'") && fcon.includes("handleOpsFinishOpt('hours'"), 'チップが無い / 時間の窓を選ぶ所が 2 つある');
