        // ソフトキーボード中は下部ナビを隠す
        assert.ok(/body\.kb-open \.bottom-nav \{ display: none !important; \}/.test(html));
        assert.ok(/document\.addEventListener\('focusin'/.test(html) && /classList\.add\('kb-open'\)/.test(html));
