        assert.deepEqual(dom.normalizeOverload(null), {});
        // ★ 読む入口 (byPlayerCharacter) で寄せる — ここを通さないと順位も比較も同じ項目が2つに割れる
        const by = dom.byPlayerCharacter([{ player_id: 1, character_name: 'X', overload: { 属性ダメージ: 7 } }]);
