    test('★ 2列/12カラム: 各段階とメンバー画面で、行の span 合計が 12 に揃う (7 の隣に 12 が来ると 7 が独りになる)', () => {
        // ★ 2026-09-11 まで実際そうなっていた: ボス7 → 残り12 → 締め凸5 の順で、7 と 5 が一度も隣り合わず全段階で1列。
        //   「span がある」「表は 12」だけでは気づけない。グリッドの自動配置をなぞって行を切り、合計を見る。
        const lay = _grLayout, st = globalThis.opsStageDomain;
        const rows = (spans) => {
            const out = []; let cur = [], w = 0;
            for (const s of spans) { if (w + s > 12) { out.push(cur); cur = []; w = 0; } cur.push(s); w += s; }
            if (cur.length) out.push(cur);
            return out;
        };
        assert.deepEqual(rows([7, 12, 5]), [[7], [12], [5]], 'この検査自体が効いていること (改行をなぞれていない)');
        // 🧱 段階 2.5: 運営の画面はタブで出し分ける (段階では出し入れしない) → タブごとに見る
        const views = {
            '👥 メンバー': lay.CARDS.filter(c => c.tab === 'members'),
            '🧱 組む': lay.CARDS.filter(c => c.tab === 'build'),
            '⚔️ 戦況': lay.CARDS.filter(c => c.tab === 'battle'),
            '👑 マスター': lay.CARDS.filter(c => c.tab === 'master'),
        };   // 「メンバー (運営OFF)」の並びは見ない: メンバーに運営タブは無い (2026-10-22) し、運営OFF 向けだった オンライン・残り戦闘可能 のカードは 2026-11-16 に撤去した
        assert.equal(lay.CARDS.length, Object.values(views).reduce((s, v) => s + v.length, 0), 'どのタブにも入らないカードがある');
        for (const [name, cards] of Object.entries(views)) {
            assert.ok(cards.length > 0, `${name}: カードが1枚も無い`);
            const rs = rows(cards.map(c => c.span));
            const bad = rs.filter(r => r.reduce((a, b) => a + b, 0) !== 12);
            assert.deepEqual(bad, [], `${name}: 12 に揃わない行がある ${JSON.stringify(rs)} — 並び: ${cards.map(c => `${c.id}(${c.span})`).join(' → ')}`);
        }
    });
    test('★ 2列/12カラム: 戦況以外の4タブは本文直下のカード全部に data-span がある (無いと黙って全幅 = 1列のまま)', () => {
        // ★ 戦況タブは opsLayout.CARDS → data-span を初期化で写す (別のテスト)。他の4タブは HTML に直接書く。
        //   700px〜 は 12 以外すべて半分なので、値の細かさより「付いているか」が効く。
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const css = html.slice(html.indexOf('<style'), html.lastIndexOf('</style>'));
        // タブ本文を切り出し、.container 直下の .dc-card だけ集める (入れ子のカードは数えない)
        const topCards = (tabId) => {
            const start = html.indexOf(`<div id="${tabId}" class="tab-content`);
            assert.ok(start > 0, `${tabId} が無い`);
            const from = html.indexOf('<div class="container"', start);
            const re = /<div\b[^>]*>|<\/div>/g; re.lastIndex = html.indexOf('>', from) + 1;
            const out = []; let d = 0, m;
            while ((m = re.exec(html))) {
                if (m[0][1] === '/') { d--; if (d < 0) break; continue; }
                //   📊 実績の左の列 (.ana-left = グラフ 2 つの縦並び・2026-11-25) は列ごと 1 つの枠として数える (中のカードは列の中)
                if (d === 0 && /^<div class="(?:dc-card|ana-left)/.test(m[0])) {
                    const chunk = html.slice(m.index, m.index + 600);
                    const t = chunk.match(/>([^<]{2,40})<\/div>/);
                    out.push({ tag: m[0], title: t ? t[1].trim() : '' });
                }
                d++;
            }
            return out;
        };
        const missing = [], bad = [];
        const found = {};
        for (const tab of ['tab-mypage', 'tab-ranking', 'tab-settings']) {
            const cards = topCards(tab);
            assert.ok(cards.length >= 3, `${tab}: 本文直下のカードが少なすぎる (${cards.length}) — 切り出しが壊れている`);
            found[tab] = cards;
            for (const c of cards) {
                const m = c.tag.match(/ data-span="(\d+)"/);
                if (!m) missing.push(`${tab}: ${c.tag.slice(0, 70)}`);
                else if (!['4', '5', '6', '7', '8', '12'].includes(m[1])) bad.push(`${tab}: data-span="${m[1]}" (CSS に受け皿が無い)`);
            }
        }
        assert.deepEqual(missing, [], `data-span の無いカード:\n  ${missing.join('\n  ')}`);
        assert.deepEqual(bad, [], bad.join('\n'));
        // 表・横に広い中身は全幅 (半分に切ると読めない)
        const spanOf = (tab, id) => (found[tab].find(c => c.tag.includes(`id="${id}"`)) || {}).tag?.match(/ data-span="(\d+)"/)?.[1];
        assert.equal(spanOf('tab-mypage', 'myAvailStripCard'), '12', '参加可能時間 (24時間の帯) は全幅であること');
        const setSpans = found['tab-settings'].map(c => c.tag.match(/ data-span="(\d+)"/)?.[1]);
        assert.equal(setSpans.filter(v => v === '12').length, 1, '設定の全幅は キャラクターマスタ管理 の 1 枚だけ (メンバー管理は 2026-09-12 に 👑 区画で 6 に)');
        // ホームの締め凸依頼の箱 (カードでない空の div): 空のとき行を占有しない
        // ★ 「どこかに innerHTML = '' がある」では弱い (2 か所のうち 1 か所を空白にしても通る — 変異で発覚)。
    });
