    await testAsync('★ 実行: 代理登録の印 (actorName) は 31 未適用の劣化経路 (supabaseSavePlayerDamage) でも活動ログに残る / 本人の提出には付かない (Codex指摘 adae2da)', async () => {
        const client = _grRd('js', 'supabase-client.js').split(String.fromCharCode(13)).join('');
        const pick = (name) => { const m = client.match(new RegExp(`window\\.${name} = async function[\\s\\S]*?\\n\\};\\n`)); assert.ok(m, `${name} が見つからない`); return m[0]; };
        const logs = [];
        // 偽の window: mockLevelsDomain が無い = 31 未適用の劣化経路。upsert は成功、ログは控えるだけ
        const w = { supabaseLogActivity: (type, detail, opts) => { logs.push({ type, detail, opts }); }, supabaseSaveTeamForAttribute: async () => {} };
        const stubs = `const _normBossLevel = (v) => (v == null ? null : Number(v)); const _exclusionClear = () => ({}); const _upsertPlayerDamages = async () => ({ error: null });
            const _loadDamageRowForMerge = async () => ({ legacy: true, failed: false, row: null }); const _loadDamageRowsForAttr = async () => ({ legacy: true, failed: false, rows: null });`;
        new Function('window', `${stubs}\n${pick('supabaseSavePlayerDamage')}\n${pick('supabaseSaveMockSubmission')}`)(w);
        const r = await w.supabaseSaveMockSubmission(7, 'fire', { damageB: 31.2, characters: ['a', 'b'], actorName: '運営役' });
        assert.deepEqual(r, { slot: 1, redirected: false, teamChanged: false, levels: null }, '劣化経路の戻り値');
        assert.equal(logs.length, 1, 'ログは 1 回 (下位関数で 1 回だけ)');
        assert.equal(logs[0].type, 'mock_submit'); assert.equal(logs[0].opts.playerId, 7);
        assert.equal(logs[0].opts.actorName, '運営役', '代理の印 (actor_name) が劣化経路で落ちている');
        assert.ok(/ \(運営が代理で登録\)$/.test(logs[0].detail), `文末に代理の印が無い: ${logs[0].detail}`);
        await w.supabaseSaveMockSubmission(7, 'fire', { damageB: 20 });
        assert.equal(logs.length, 2); assert.equal(logs[1].opts.actorName, null); assert.ok(!/代理/.test(logs[1].detail), '本人の提出に代理の印が付いている');
    });

    await testAsync('★ 実行: 中央の取り直し (_opsReloadBoardCards) — 重なった呼び出しは最新だけが描く / 古い応答は描かない / 失敗の知らせは最新の 1 回だけ (Codex指摘 72efb1f)', async () => {
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const src = html.match(/let _opsBoardReloadSeq = 0;\n[\s\S]*?async function _opsReloadBoardCards\(\) \{[\s\S]*?\n        \}\n/)?.[0];
        assert.ok(src, '_opsReloadBoardCards が見つからない');
        // 偽の opsStore: 本物と同じ世代の規則 (応答待ちの間に新しい load が始まったら、古い応答は store に保存しない)
        const mkStore = () => { let data = null, g = 0; return {
            get: () => data,
            async load() { const gen = ++g; const job = this.next.shift(); const r = await job(); if (gen === g) data = r; return r; },
            next: [],
        }; };
        const wait = (ms) => new Promise(r => setTimeout(r, ms));
        const calls = [];
        const api = { renderOpsMemberStatus: (snap) => calls.push(['member', snap && snap.tag]), _syncOpsUnpublishBtn: async () => { calls.push(['sync']); }, renderOpsMockIntake: () => calls.push(['intake']), showNotification: (m) => calls.push(['notify', m]) };
        const build = (store) => new Function('opsStore', '_opsMode', 'renderOpsMemberStatus', '_syncOpsUnpublishBtn', 'renderOpsMockIntake', 'showNotification', `${src}\nreturn _opsReloadBoardCards;`)(store, true, api.renderOpsMemberStatus, api._syncOpsUnpublishBtn, api.renderOpsMockIntake, api.showNotification);
        // ① 遅い取り直し → すぐ速い取り直し: 速い方 (最新) だけが描く。遅い方の応答は store に残らず、描かれない
        const st = mkStore();
        st.next.push(async () => { await wait(60); return { tag: 'old', season: {}, players: [] }; });
        st.next.push(async () => { await wait(5); return { tag: 'new', season: {}, players: [] }; });
        const reload = build(st);
        const p1 = reload(); const p2 = reload();
        await Promise.all([p1, p2]); await wait(80);
        assert.deepEqual(calls, [['member', 'new'], ['sync'], ['intake']], `古い応答が描かれた / 二重に描いた: ${JSON.stringify(calls)}`);
        // ② 失敗が重なっても知らせは最新の 1 回だけ
        calls.length = 0;
        const st2 = mkStore();
        st2.next.push(async () => { await wait(40); throw new Error('遅い失敗'); });
        st2.next.push(async () => { await wait(5); throw new Error('速い失敗'); });
        const reload2 = build(st2);
        await Promise.all([reload2(), reload2()]); await wait(60);
        assert.deepEqual(calls, [['notify', '❌ 盤面の取得に失敗しました: 速い失敗']], `失敗の知らせが最新の 1 回でない: ${JSON.stringify(calls)}`);
        // ③ 盤面の描画 (renderOpsDashboard) も store に残った盤面だけを描く (load の戻り値をそのまま描かない)
        const dash = html.match(/async function renderOpsDashboard\(\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/for \(let tries = 0; !snapshot && tries < 2; tries\+\+\) \{\s*\n\s*await opsStore\.load\(\);\s*\n\s*snapshot = opsStore\.get\(\);\s*\n\s*\}/.test(dash), 'ダッシュボードが load の戻り値をそのまま描いている (追い越された古い応答で最新を上書きする)');
        assert.ok(/if \(!snapshot\) \{[\s\S]{0,400}clearTimeout\(_opsDashRetryTimer\);\s*\n\s*_opsDashRetryTimer = setTimeout\(\(\) => \{ _opsDashRetryTimer = null; if \(document\.getElementById\('tab-ops'\)\?\.classList\.contains\('active'\)\) renderOpsDashboard\(\); \}, 1500\);\s*\n\s*return;/.test(dash) && /let _opsDashRetryTimer = null;/.test(html), '追い越されて描けなかったとき、描き直しを予約せず「読み込み中...」のまま残る (Codex指摘 e6ccd65)');
        assert.ok(!/snapshot = await opsStore\.load\(\)/.test(dash), 'ダッシュボードが load の戻り値を snapshot にしている');
    });

