console.log('\n▶︎ 模擬ダメージ表 (シンプル化 S1):');
{
    const _fs9 = await import('node:fs');
    const html = _fs9.readFileSync('index.html', 'utf8').replace(/\r\n/g, '\n');
    const d = globalThis.mockIntakeDomain;
    test('★ attrOrderOfBosses: ボス 1〜5 の弱点の順 (欠けは既定の順で補う) / deadlineOf は missingRows と同じ', () => {
        const B = [{ boss_number: 3, weakness: 'fire' }, { boss_number: 1, weakness: 'iron' }, { boss_number: 2, weakness: 'electric' }, { boss_number: 5, weakness: 'water' }, { boss_number: 4, weakness: 'wind' }];
        assert.deepEqual(d.attrOrderOfBosses(B), ['iron', 'electric', 'fire', 'wind', 'water']);
        assert.deepEqual(d.attrOrderOfBosses([{ boss_number: 1, weakness: 'WIND' }, { boss_number: 2, weakness: 'x' }]), ['wind', 'fire', 'water', 'electric', 'iron'], '欠けたボスの属性を既定の順で補っていない');
        assert.deepEqual(d.attrOrderOfBosses(null), d.ATTR_KEYS);
        const blocks = globalThis.raidBlocksDomain.blocksOfSeason(null);
        assert.deepEqual(d.deadlineOf({ availableSlots: ['h18', 'h21'] }, blocks), { idx: 3, name: '夕方', short: 'D 夕方', range: '17〜21時', label: 'D 夕方 17〜21時' }); assert.equal(d.deadlineOf({ availableSlots: [] }, blocks), null); assert.equal(d.deadlineOf({ availableSlots: ['h05'], flexTime: true }, blocks), null);
    });
    test('★ tableRows: 人 × 属性 (ボス順) のマス / 被り = 同じ人の別の編成 (属性を問わず) と同じキャラ (キャラの無い編成は判定しない) / 書庫・今回は難しい は除く / 並びは 〆 → 足りない数 → 名前', () => {
        const B = [{ boss_number: 1, weakness: 'iron' }, { boss_number: 2, weakness: 'electric' }, { boss_number: 3, weakness: 'fire' }, { boss_number: 4, weakness: 'wind' }, { boss_number: 5, weakness: 'water' }];
        const blocks = globalThis.raidBlocksDomain.blocksOfSeason(null);
        const P = (id, name, slots, lo, extra = {}) => ({ id, name, availableSlots: slots, loadoutsByAttr: lo, ...extra });
        const players = [
            P(1, 'あ', ['h21'], { fire: [{ slot: 1, dmgB: 28.4, team: ['紅蓮', 'ラピ', 'アニス', 'クラウン', 'リター'] }], water: [{ slot: 1, dmgB: 24.6, team: ['ベル', 'マスト', 'ナガ', 'ティア', 'リター'] }, { slot: 2, dmgB: 19, team: ['A', 'B', 'C', 'D', 'E'] }], iron: [{ slot: 1, dmgB: 22.8, team: [] }] }),
            P(2, 'い', ['h05'], { electric: [{ slot: 1, dmgB: 0, team: [] }] }),
            P(3, 'う', [], {}),
            P(4, '書庫', ['h05'], { fire: [{ slot: 1, dmgB: 30, team: ['X'] }] }, { archived: true }),
            P(5, '難', ['h05'], { fire: [{ slot: 1, dmgB: 30, team: ['X'] }] }, { unavailableThisSeason: true }),
        ];
        const t = d.tableRows({ players, blocks, bosses: B, b5Weakness: 'water' });
        assert.deepEqual(t.attrs, ['iron', 'electric', 'fire', 'wind', 'water']);
        assert.deepEqual(t.rows.map(r => r.name), ['い', 'あ', 'う'], '並び (〆 朝 → 夜 → いつでも) が違う / 書庫・難しい を除いていない');
        const a = t.rows.find(r => r.name === 'あ');
        assert.deepEqual(a.cells.fire, [{ slot: 1, dmgB: 28.4, team: ['紅蓮', 'ラピ', 'アニス', 'クラウン', 'リター'], dup: true }], '属性をまたぐ被り (リター) を見ていない');
        assert.deepEqual(a.cells.water.map(c => [c.slot, c.dup]), [[1, true], [2, false]], '同じ属性の 2 つ目 (別キャラ) を被りにしている');
        assert.deepEqual(a.cells.iron, [{ slot: 1, dmgB: 22.8, team: [], dup: false }], 'キャラの無い編成を被りにしている');
        assert.deepEqual([a.submitted, a.missing, a.b5Short, a.deadline], [3, ['electric', 'wind'], 0, { idx: 4, name: '夜', short: 'E 夜', range: '21〜翌1時', label: 'E 夜 21〜翌1時' }]);
        const i = t.rows.find(r => r.name === 'い');
        assert.deepEqual([i.cells.electric, i.missing.length, i.deadline], [[], 5, { idx: 0, name: '朝', short: 'A 朝', range: '5〜9時', label: 'A 朝 5〜9時' }], 'ダメージ 0・キャラ無しの行を模擬に数えている');
        const u = t.rows.find(r => r.name === 'う'); assert.deepEqual([u.noSlots, u.deadline, u.submitted], [true, null, 0]);
        assert.deepEqual(d.tableRows({}), { attrs: d.ATTR_KEYS, rows: [] });
    });
    test('★ ✏️ まとめて入力 (1 人 5 属性・第46期メモ §3): presetsFor の並び (今回の模擬 → 過去の凸 → 人数)・前回の自分・被り / bulkSaves は変えた枠だけ・ダメージのある枠だけ / onlyBlockOf / markDup', () => {
        const d = globalThis.mockIntakeDomain;
        const T = (s) => s.split('');
        const popular = [
            { team: T('abcde'), count: 9, mockCount: 1, histCount: 8 },   // 人数は多いが今回の模擬は 1
            { team: T('fghij'), count: 4, mockCount: 4, histCount: 0 },   // 今回の模擬 4 → 先頭 (Q4)
            { team: T('klmno'), count: 5, mockCount: 1, histCount: 4 },   // 模擬 1 は同じ → 過去の凸 4 < 8 → 3 番目
            { team: T('pqrst'), count: 1, mockCount: 0, histCount: 1 },
            { team: T('abcd'), count: 99, mockCount: 99, histCount: 0 },  // 4 人しか無い → 出さない
            { team: ['e', 'd', 'c', 'b', 'a'], count: 3, mockCount: 3, histCount: 0 },   // 同じ 5 人 (並びだけ違う) → 1 つにまとめる (人数はそれぞれ大きいほう: 9 人・模擬 3・凸 8)
        ];
        const r1 = d.presetsFor({ popular });
        assert.deepEqual(r1.map(p => p.key), ['f|g|h|i|j', 'a|b|c|d|e', 'k|l|m|n|o', 'p|q|r|s|t'], '並びが 今回の模擬 → 過去の凸 → 人数 でない / 4 人の編成・同じ 5 人の重複を出した');
        assert.ok(r1.every(p => p.source === 'popular' && !p.mine && !p.dup && p.dupWith.length === 0), 'popular の印');
        assert.deepEqual([r1[1].count, r1[1].mockCount, r1[1].histCount], [9, 3, 8], '同じ 5 人の 2 行をまとめていない');
        // 前回の自分: 人気に無ければ後ろに足す (source last・mine)・人気にあればその行に mine・5 人そろわない (解決できなかった) 凸と同じ編成の 2 回目は捨てる
        const r2 = d.presetsFor({ popular, lastRaid: [T('abcde'), T('uvwxy'), ['a', 'b', null, 'd', 'e'], T('uvwxy')] });
        assert.deepEqual(r2.map(p => [p.key, p.source, p.mine]), [['f|g|h|i|j', 'popular', false], ['a|b|c|d|e', 'popular', true], ['k|l|m|n|o', 'popular', false], ['p|q|r|s|t', 'popular', false], ['u|v|w|x|y', 'last', true]]);
        // 上限: limit で人気を切る。切られた人気と同じ前回の自分は人数つきで後ろに
        const r3 = d.presetsFor({ popular, lastRaid: [T('pqrst')], limit: 2 });
        assert.deepEqual(r3.map(p => [p.key, p.source, p.count]), [['f|g|h|i|j', 'popular', 4], ['a|b|c|d|e', 'popular', 9], ['p|q|r|s|t', 'last', 1]]);
        // 被り: 別の属性の編成 (others) と重なれば dup = 注意の印だけ (選べる) / 同じ属性のほかの枠 (blockers) と重なれば blocked = 選べない
        const r4 = d.presetsFor({ popular, others: [T('e1234'), T('zzzzz')], blockers: [T('k9999')] });
        assert.deepEqual(r4.map(p => [p.key, p.dup, p.dupWith, p.blocked, p.blockedWith]),
            [['f|g|h|i|j', false, [], false, []], ['a|b|c|d|e', true, ['e'], false, []], ['k|l|m|n|o', false, [], true, ['k']], ['p|q|r|s|t', false, [], false, []]]);
        assert.ok(d.presetsFor({ popular }).every(p => !p.dup && !p.blocked && p.dupWith.length === 0 && p.blockedWith.length === 0), 'others / blockers 無しで被りが立つ');
        assert.deepEqual(d.presetsFor({}), [], '材料なしで落ちる');
        // ref は画面の札 (中身は見ない・そのまま返す)。無ければ付けない
        assert.deepEqual(d.bulkSaves([{ attr: 'iron', slot: 1, damageB: 1, team: [], dirty: true, ref: 'R' }]).saves, [{ attr: 'iron', slot: 1, damageB: 1, characters: null, ref: 'R' }]);
        // bulkSaves: 変えた枠だけ・ダメージのある枠だけ (Q5 / Q6)
        const rows = [
            { attr: 'iron', slot: 1, damageB: 30, team: T('abcde'), dirty: true },
            { attr: 'fire', slot: 2, damageB: 20.5, team: ['', '', '', '', ''], dirty: true },   // 編成なし = キャラは null
            { attr: 'water', slot: 1, damageB: 25, team: T('fghij'), dirty: false },             // 変えていない → 保存しない
            { attr: 'wind', slot: 1, damageB: null, team: T('klmno'), dirty: true },            // 編成だけ → 保存しない (Q6)
            { attr: 'electric', slot: 9, damageB: 1, team: [], dirty: true },                   // 枠の番号が壊れていれば ①
            { attr: 'nope', slot: 1, damageB: 1, team: [], dirty: true },
        ];
        assert.deepEqual(d.bulkSaves(rows), {
            saves: [{ attr: 'iron', slot: 1, damageB: 30, characters: T('abcde') }, { attr: 'fire', slot: 2, damageB: 20.5, characters: null }, { attr: 'electric', slot: 1, damageB: 1, characters: null }],
            skipped: [{ attr: 'water', slot: 1, why: 'unchanged' }, { attr: 'wind', slot: 1, why: 'no_damage' }],
        });
        assert.deepEqual(d.bulkSaves(null), { saves: [], skipped: [] });
        // onlyBlockOf / tableRows.only: 出られるブロックが 1 つだけの人 (= blockBuild.lockKind の only)
        const blocks = globalThis.raidBlocksDomain.blocksOfSeason({ metadata: {} });
        const P = (slots) => ({ id: 1, name: 'x', availableSlots: slots, loadoutsByAttr: {} });
        assert.deepEqual(d.onlyBlockOf(P(['h17', 'h18']), blocks), { idx: 3, short: blocks[3].short, label: blocks[3].label });
        assert.equal(d.onlyBlockOf(P(['h17', 'h22']), blocks), null, '2 つのブロックに出られる人を「のみ」にした');
        assert.equal(d.onlyBlockOf(P([]), blocks), null, '時間未登録を「のみ」にした');
        assert.equal(d.onlyBlockOf({ ...P(['h17']), flexTime: true }, blocks), null, '⏳隙間を「のみ」にした');
        assert.equal(d.tableRows({ players: [P(['h17'])], blocks, bosses: [] }).rows[0].only.idx, 3, '表の行に only が無い');
        assert.equal(d.tableRows({ players: [P(['h17', 'h22'])], blocks, bosses: [] }).rows[0].only, null);
        // markDup = 表の赤い枠と同じ判定 (キャラの無い編成は判定しない)
        const L = [{ team: T('abcde') }, { team: T('e1234') }, { team: [] }, { team: T('vwxyz') }];
        assert.deepEqual(d.markDup(L).map(x => x.dup), [true, true, false, false]);
        assert.equal(d.keyOf(['b', 'a', 'a', '', null]), 'a|b');
    });

    test('★ 配線: ✏️ まとめて入力 — 表の名前 → openOpsMockBulk / モーダル / 保存は _saveMockFor (本人の提出と同じ経路) を変えた枠だけ順に / プリセットは開くたびに読み直す / 次の人は表の並び', () => {
        assert.ok(/<div class="player-select-modal" id="opsMockBulkModal" data-ops-only>/.test(html) && /id="opsMockBulkBody"/.test(html), 'モーダルが無い');
        const r = html.slice(html.indexOf('async function renderOpsMockIntake'), html.indexOf('async function handleOpsMockIntakeUpload'));
        assert.ok(/\$\{r\.only \? `<span class="mk-only"/.test(r), '「このブロックのみ」の印が無い');
        assert.ok(/_mockIntake\.order = tbl\.rows\.map\(r => Number\(r\.id\)\);/.test(r), '次の人の並びを控えていない');
        const m = html.slice(html.indexOf('const _mkb = {'), html.indexOf('// ========== 👥 メンバー状況ボード'));
        assert.ok(m.length > 1000, 'まとめて入力の本体が見つからない');
        assert.ok(/await Promise\.allSettled\(\[_loadTeamSubs\(true\), _mkbLoadPrevSeason\(\)\]\);/.test(m), 'プリセットの材料を開くたびに読み直していない (Q4)');
        assert.ok(/if \(gen !== _mkb\.gen\) return;/.test(m), '世代ガードが無い');
        assert.ok(/const \{ saves \} = dom\.bulkSaves\(flat\);/.test(m) && /await _saveMockFor\(pid, s\.attr, \{ damageB: s\.damageB, slot: s\.slot, characters: s\.characters, actorName \}\);/.test(m), '保存が bulkSaves → _saveMockFor でない');
        assert.ok(!/supabaseSaveMockSubmission|supabaseRegisterOcrCharacters/.test(m), 'まとめて入力が保存の RPC を直に呼んでいる (経路を増やさない)');
        assert.ok(/window\.mockIntakeDomain\.presetsFor\(\{ popular: _mkb\.pop\[attr\] \|\| \[\], lastRaid: _mkb\.last\[attr\] \|\| \[\], others: _mkbOthers\(attr, i\), blockers: _mkbOthers\(attr, i, true\) \}\)/.test(m), 'プリセットをドメインで作っていない (別の属性 = others / 同じ属性 = blockers)');
        assert.ok(/if \(p\.blocked\) \{ showNotification\(/.test(m) && !/if \(p\.dup\) \{ showNotification/.test(m), '同じ属性の被りで止めていない / 別の属性の被りで止めている');
        assert.ok(/const row = s\.ref \|\| null;/.test(m) && /const teamKey = _mkbKey\(s\.characters \|\| \[\]\);/.test(m), '行を札で引いていない / 保存した時点の編成の鍵を控えていない (Codex P1 / P2)');
        assert.ok(/const tgt = to !== s\.slot \? rows\.find\(x => x !== row && Number\(x\.slot\) === to\) \|\| null : null;/.test(m) && /rows\.splice\(at, 1\);/.test(m), '統合先の行に寄せて元の行を消していない (Codex P1)');
        assert.ok(/if \(tgt && !s\.retried && queue\.slice\(qi \+ 1\)\.some\(q => q\.ref === tgt\)\) \{/.test(m) && /queue\.push\(\{ \.\.\.s, retried: true \}\);/.test(m), '寄せ先が変更中のときに保存し直していない (Codex 再監査 A②)');
        assert.ok(/if \(_mkb\.busy\) \{ showNotification\('保存中なので反映しませんでした/.test(m) && /MY_TEAM_SLOTS\.includes\(Number\(l\.slot\)\) && \(Number\(l\.dmgB\) > 0/.test(m), '保存中のピッカーの結果を捨てていない / 壊れた枠番号の行を読んでいる');
        assert.ok(/opsStore\.invalidate\(\);\s*\n\s*_opsReloadBoardCards\(\);/.test(m), '保存後に盤面を取り直していない');
        assert.ok(/data-key="\$\{escapeHtml\(p\.key\)\}" onclick="_mkbPick\('\$\{a\}', \$\{i\}, this\.dataset\.key\)"/.test(m), 'プリセットの鍵を onclick に埋めている (名前は onclick に埋めない)');
        assert.ok(/if \(_mkb\.busy\) \{ showNotification\('保存中です/.test(m), '保存中に閉じられる / 開き直せる');
        // 本人の提出 (handleMyDmgPreviewSave) も同じ保存関数を通る。保存の RPC を直に呼ぶのは _saveMockFor と 従来の編成編集 (entries 付き) の 2 か所だけ
        const pv = html.slice(html.indexOf('async function handleMyDmgPreviewSave()'), html.indexOf('async function detectPtAttrFromBossName'));
        assert.ok(/const res = await _saveMockFor\(id\.id, attr, \{/.test(pv) && !/supabaseRegisterOcrCharacters/.test(pv), '本人の提出が _saveMockFor を通っていない');
        assert.equal((html.match(/window\.supabaseSaveMockSubmission\(/g) || []).length, 1, '保存の RPC を呼ぶ場所が増えた (_saveMockFor だけ — 従来の編成編集は 2026-11-16 に撤去)');
        const sv = html.slice(html.indexOf('async function _saveMockFor('), html.indexOf('async function handleMyDmgPreviewSave()'));
        assert.ok(/supabaseRegisterOcrCharacters\(characters\)/.test(sv) && /characters: canon && canon\.length > 0 \? canon : null,/.test(sv), '_saveMockFor がキャラをマスタで正規化していない');
    });

    test('★ 配線: 📸 のカードが表 (tableRows・ボス順の見出し・属性の薄い地・＋ と編成の押下 → _opsMockManual・名前 → 読み取り) / ✏️ 手で入力 / プレビューは手入力のときダメージの欄・見出し・再撮影なし / キャラ選びは属性の採用数の順', () => {
        const r = html.slice(html.indexOf('async function renderOpsMockIntake'), html.indexOf('async function handleOpsMockIntakeUpload'));
        assert.ok(/const tbl = dom\.tableRows\(\{ players, blocks, bosses: snap\.bosses \|\| \[\], b5Weakness: b5Weak \}\);/.test(r), '表の行をドメインで作っていない');
        assert.ok(/<table class="mk-tbl">/.test(r) && /data-no-swipe/.test(r), '表が無い / 横スクロールの箱に data-no-swipe が無い');
        assert.ok(/onclick="_opsMockManual\(\$\{Number\(r\.id\)\}, '\$\{a\}', \$\{Number\(c\.slot\)\}\)"/.test(r) && /onclick="_opsMockManual\(\$\{Number\(r\.id\)\}, '\$\{a\}'\)"/.test(r), '編成を押して直す / ＋ で手入力 が無い');
        assert.ok(/class="mk-chip\$\{c\.dup \? ' dup' : ''\}"/.test(r), '被りの赤い枠が無い');
        // 名前 → ✏️ まとめて入力 (第46期メモ §3)。押すとファイル選択が開く 2 つ目の入口 (2026-10-29 に消した) は戻さない
        assert.ok(/<td><button type="button" class="mk-name btn" onclick="openOpsMockBulk\(\$\{Number\(r\.id\)\}\)"[^>]*>\$\{escapeHtml\(r\.name\)\}<\/button>/.test(r) && !html.includes('_opsMockIntakePickFromList'), '名前が まとめて入力 を開かない');
        assert.ok(/const plus = \(list\.length === 0 \|\| \(a === b5Weak && r\.b5Short > 0 && list\.length < MY_TEAM_SLOTS\.length\)\) \? `<button type="button" class="mk-plus"/.test(r), '埋まったマスにも ＋ が出る / 3 編成そろったマスにも出る (段階 3 続き: 空のマスと、ボス 5 の 2 編成目が足りない人のマスだけ)');
        // 手で入力の入口は表のマスの ＋ / 編成のチップ (カードの「✏️ 手で入力」は同じ操作の 2 つ目だった — 2026-10-29 ボタンの監査)
        assert.ok(!/onclick="_opsMockManual\(\)"/.test(html) && /_opsMockManual\(\$\{Number\(r\.id\)\}/.test(html), '✏️ 手で入力 が 2 つある / 表から手入力できない');
        const m = html.slice(html.indexOf('function _opsMockManual(playerId, attr, slot)'), html.indexOf('async function handleOpsMockIntakeUpload'));
        assert.ok(/files: \[\], manual: true,/.test(m) && /forPlayer: \{ id: Number\(target\.id\), name: target\.name \},/.test(m) && /\.\.\.\(cur \? \{ slot: Number\(cur\.slot\), slotTouched: true \} : \{\}\),/.test(m) && /openMyDmgPreviewModal\(\);/.test(m), '手入力がプレビュー (読み取りと同じ保存の経路) を使っていない');
        assert.ok(/if \(!target\) \{ fail\('先に「誰の模擬か」を選んでください'\); return; \}/.test(m), '誰のか決まらずに開ける');
        const pv = html.slice(html.indexOf('function openMyDmgPreviewModal()'), html.indexOf('async function handleMyDmgPreviewSave()'));
        assert.ok(/id="myDmgPreviewDmgInput" type="number" inputmode="decimal" step="0\.01" min="0"[^>]*oninput="_myDmgPreviewSetDamage\(this\.value\)"/.test(pv), '手入力のダメージの欄が無い');
        assert.ok(/titleEl\.innerHTML = d\.manual \? '✏️ 模擬を手で入力'/.test(pv) && /retryBtn\.style\.display = d\.manual \? 'none' : ''/.test(pv), '手入力の見出し / 再撮影の非表示');
        assert.ok(/warns\.push\(d && d\.manual \? 'ダメージ \(B\) を入力してください' : 'ダメージ値が読めませんでした'\);/.test(html) && /const warns = _myDmgPreviewWarns\(d\);/.test(pv) && /\$\{d\.manual \? 'アイコンをタップして選びます \(任意・よく使われる順\)' : '認識ミスはアイコンをタップして修正できます'\}/.test(pv), '手入力なのに「読めませんでした」「認識ミス」と出る');
        // 実行: ダメージの欄に入れると保存ボタンが有効になる (Codex 監査 S1: 値を書くだけでボタンが無効のままだった)
        const src = html.slice(html.indexOf('function _myDmgPreviewSetDamage(v)'), html.indexOf('function editMyDmgPreviewChar(i)')) + '\n' + html.slice(html.indexOf('function _myDmgPreviewSyncSave()'), html.indexOf('async function handleMyDmgPreviewSave()'));
        const mkDoc = () => { const els = { myDmgPreviewSaveBtn: { disabled: true, style: {} }, myDmgPreviewWarn: { style: { display: 'flex' } }, myDmgPreviewWarnText: { textContent: '' } }; return { getElementById: (id) => els[id] || null, els }; };
        const run = (data, inputs) => { const doc = mkDoc(); const fns = new Function('document', '_myDmgPreviewData', 'PT_ATTRS', src + '\nreturn { set: _myDmgPreviewSetDamage, sync: _myDmgPreviewSyncSave };')(doc, data, [{ key: 'fire' }, { key: 'water' }]); fns.sync(); for (const v of inputs) fns.set(v); return { ok: !doc.els.myDmgPreviewSaveBtn.disabled, dmg: data.totalDamage, warn: doc.els.myDmgPreviewWarn.style.display, text: doc.els.myDmgPreviewWarnText.textContent }; };
        assert.deepEqual(run({ manual: true, selectedAttr: 'water', totalDamage: null }, ['28.4']), { ok: true, dmg: 28400000000, warn: 'none', text: '' }, '入力しても保存できない');
        assert.deepEqual(run({ manual: true, selectedAttr: 'water', totalDamage: null }, []), { ok: false, dmg: null, warn: 'flex', text: '' }, 'ダメージ無しで保存できる');
        assert.deepEqual(run({ manual: true, selectedAttr: 'water', totalDamage: null }, ['28.4', '']).ok, false, '消したのに保存できる');
        assert.equal(run({ manual: true, selectedAttr: 'water', totalDamage: null }, ['28.4', '']).text, 'ダメージ (B) を入力してください');
        const na = run({ manual: true, selectedAttr: null, totalDamage: null }, ['28.4']); assert.equal(na.ok, false, '属性なしで保存できる'); assert.deepEqual([na.warn, na.text], ['flex', '属性が判別できませんでした。下のボタンから選んでください'], '属性なしのとき古い「入力してください」が残る / 属性の警告が出ない (Codex 再監査)');
        assert.deepEqual(run({ manual: false, selectedAttr: 'fire', totalDamage: null }, ['0']).dmg, null); assert.deepEqual(run({ manual: false, selectedAttr: 'fire', totalDamage: null }, ['-3']).ok, false);
        assert.deepEqual(run({ manual: false, selectedAttr: 'fire', totalDamage: null }, ['1e400']).ok, false, 'Infinity を保存できる');
        assert.ok(/_myDmgPreviewSyncSave\(\);\s*\n\s*modal\.classList\.add\('open'\);/.test(pv), '開いたときに同じ判定を通していない');
        assert.ok(/const raw = Number\.isFinite\(n\) && n > 0 \? Math\.round\(n \* 1e9\) : null;\s*\n\s*d\.totalDamage = Number\.isFinite\(raw\) \? raw : null;/.test(html), 'ダメージの欄が totalDamage (生の値) に書いていない');
        assert.ok(/\}, `📚 編成の修正 \(\$\{i \+ 1\}枠目\)`, \{ attr: d\.selectedAttr \|\| null \}\);/.test(html), 'キャラ選びが属性の採用数の順になっていない (Q1)');
        assert.ok(/const _MK_ATTR_CSS = \{/.test(html) && /fire: \{ bg: 'var\(--attr-fire-bg\)', deep: 'var\(--attr-fire-deep\)' \}/.test(html), '属性の色がトークンでない');
        assert.ok(/\.mk-chip\.dup, \.mk-dup-sample \{ border-color: var\(--bad\); \}/.test(html), '被りの枠の色がトークンでない');
    });
}

