console.log('\n✅ 決定 (decidePlan・シンプル化 S4):');
{
    const dp = globalThis.decidePlanDomain, rbx = globalThis.raidBlocksDomain;
    const blocks = rbx.normalize(rbx.DEFAULT_BLOCKS).blocks;
    const bosses = [1, 2, 3, 4, 5].map(n => ({ boss_number: n, name: `ボス${n}`, weakness: ['fire', 'water', 'wind', 'iron', 'electric'][n - 1], tier: 'lord' }));
    const piece = (memberId, dmgB, hourIdx, o = {}) => ({ memberId, memberName: `m${memberId}`, dmgB, team: [`c${memberId}a`, `c${memberId}b`], loadoutSlot: 1, hourIdx, hourLabel: `${hourIdx + 5}時`, ...o });
    // 朝 (idx 0) Lv1: B1 に 1 と 2 / B2 に 3。午前 (idx 1) Lv1: B3 に 1 (編成②)
    const ov = [
        { idx: 0, past: false, level: 1, rows: [{ bossNumber: 1, name: 'ボス1', weakness: 'fire', pieces: [piece(1, 30, 1), piece(2, 20, 0)] }, { bossNumber: 2, name: 'ボス2', weakness: 'water', pieces: [piece(3, 10, 2)] }] },
        { idx: 1, past: false, level: 1, rows: [{ bossNumber: 3, name: 'ボス3', weakness: 'wind', pieces: [piece(1, 15, 4, { loadoutSlot: 2, pinned: true, reservationId: 77 })] }] },
    ];
    test('★ build: 組めたブロックの実行される凸をレベル → ボスにまとめる・時刻はブロックの中・ブロックの鍵と名前を付ける', () => {
        const p = dp.build({ blocks, ov, newIdxs: [0, 1], bosses, at: 'T' });
        assert.deepEqual(p.decided.blocks.map(b => [b.key, b.idx, b.level, b.kept, b.attacks]), [['5-8', 0, 1, false, 3], ['9-12', 1, 1, false, 1]]);
        assert.equal(p.decided.upTo, 1); assert.equal(p.decided.at, 'T'); assert.equal(p.timeAware, true);
        assert.deepEqual(p.levels.map(l => l.level), [1]);
        assert.deepEqual(p.levels[0].bosses.map(b => [b.bossNumber, b.name, b.weakness, b.attacks.map(a => a.memberId)]), [[1, 'ボス1', 'fire', [2, 1]], [2, 'ボス2', 'water', [3]], [3, 'ボス3', 'wind', [1]]]);
        const a = p.levels[0].bosses[2].attacks[0];
        assert.equal(a.block, '9-12'); assert.equal(a.blockLabel, blocks[1].label); assert.equal(a.pinned, true); assert.equal(a.reservationId, 77); assert.equal(a.loadoutSlot, 2);
        assert.ok(!('_meta' in a) && !('level' in a), '中の印が残っている');
    });
    test('★ build: 今回決めないブロックは前の決定から写す (kept)・前にも無ければ入れない・過ぎたブロックも前の決定のまま', () => {
        const prev = dp.build({ blocks, ov: [ov[0], { ...ov[1] }, { idx: 2, past: false, level: 2, rows: [{ bossNumber: 4, name: 'ボス4', weakness: 'iron', pieces: [piece(5, 40, 8)] }] }], newIdxs: [0, 1, 2], bosses });
        const next = dp.build({ blocks, ov: [{ idx: 0, past: true, level: null, rows: [] }, { idx: 1, past: false, level: 1, rows: [{ bossNumber: 5, name: 'ボス5', weakness: 'electric', pieces: [piece(9, 50, 5)] }] }], newIdxs: [1], prevPlan: prev, bosses });
        assert.deepEqual(next.decided.blocks.map(b => [b.key, b.kept, b.level, b.attacks]), [['5-8', true, 1, 3], ['9-12', false, 1, 1], ['13-16', true, 2, 1]]);
        assert.deepEqual(dp.flat(next).map(a => [a.block, a.memberId, a.bossNumber, a.level]).sort(), [['13-16', 5, 4, 2], ['5-8', 1, 1, 1], ['5-8', 2, 1, 1], ['5-8', 3, 2, 1], ['9-12', 9, 5, 1]].sort());
        const none = dp.build({ blocks, ov: [ov[0]], newIdxs: [0, 3], bosses });
        assert.deepEqual(none.decided.blocks.map(b => b.key), ['5-8'], '組んでいない (ov に無い) ブロックを入れた');
    });
    test('★ 変更なしの決定し直し (2026-11-02 ふるり・メモ §1): newIdxs が空の build は前の決定と同じ中身・notices は 0 通 / sameNotices は いまのブロックから後ろに済んでいない凸がある人だけ', () => {
        const prev = dp.build({ blocks, ov, newIdxs: [0, 1], bosses, at: 'T1' });
        // 画面は ov を渡すが、newIdxs が空なら ov は読まない (いまの盤面で作り直さない = S4 レビュー [2])
        const again = dp.build({ blocks, ov: [{ idx: 0, past: false, level: 2, rows: [{ bossNumber: 4, name: 'ボス4', weakness: 'iron', pieces: [piece(8, 99, 0)] }] }], newIdxs: [], prevPlan: prev, bosses, at: 'T2' });
        assert.deepEqual(again.decided.blocks.map(b => [b.key, b.level, b.attacks, b.kept]), prev.decided.blocks.map(b => [b.key, b.level, b.attacks, true]), 'ブロックが前の決定と違う');
        const sig = (p) => dp.flat(p).map(a => `${a.block}|${a.level}|${a.bossNumber}|${a.memberId}|${a.loadoutSlot}|${a.hourIdx}|${a.dmgB}|${(a.team || []).join(',')}`).sort().join('\n');
        assert.equal(sig(again), sig(prev), '凸の中身が前の決定と違う (いまの盤面で作り直した)');
        assert.equal(again.decided.at, 'T2', '確かめた時刻が残らない');
        assert.equal(dp.isDecided(again), true);
        assert.deepEqual(dp.notices({ prevPlan: prev, nextPlan: again, blocks }).notices, [], '変更なしなのに通知が出る');
        const pt = (w) => ({ fire: '灼熱', water: '水冷', wind: '風圧' })[w] || '';
        // 朝 (0) に 1・2・3、午前 (1) に 1 (編成②)
        const all = dp.sameNotices({ plan: again, blocks, fromIdx: 0, ptName: pt });
        assert.deepEqual(all.map(n => n.memberId), [1, 2, 3]);
        assert.ok(all.every(n => n.same === true && n.changed === false && n.sig === 'same' && n.title === '📅 あなたの凸は変わりません'));
        const m1 = all.find(n => n.memberId === 1);
        assert.deepEqual(m1.lines, [`${blocks[0].label} Lv1 B1 灼熱PT 編成①`, `${blocks[1].label} Lv1 B3 風圧PT 編成②`]);
        assert.ok(m1.body.startsWith(m1.lines.join(' / ') + ' — ') && /前の決定のまま/.test(m1.body) && /レイド予定表で確認できます$/.test(m1.body));
        // いまのブロックが午前 (1) なら朝の凸は過ぎた → 午前に凸のある 1 だけ (朝の 1 行は出さない)
        assert.deepEqual(dp.sameNotices({ plan: again, blocks, fromIdx: 1 }).map(n => [n.memberId, n.lines.length]), [[1, 1]]);
        // 済んだ凸 (✓ の planKey) は数えない: 2 は全部済み → 送らない / 1 は朝が済み → 午前の 1 行だけ
        const done = new Set(dp.flat(again).filter(a => a.memberId === 2 || (a.memberId === 1 && a.block === '5-8')).map(a => dp.planKey(a)));
        assert.deepEqual(dp.sameNotices({ plan: again, blocks, fromIdx: 0, done }).map(n => [n.memberId, n.lines.length]), [[1, 1], [3, 1]]);
        assert.deepEqual(dp.sameNotices({ plan: again, blocks, fromIdx: blocks.length }), [], 'ブロックが全部過ぎたのに送る');
        // シーズンのブロックに無い鍵の凸 (過ぎたかどうか分からない) の人には送らない
        const odd = JSON.parse(JSON.stringify(again));
        odd.levels[0].bosses[0].attacks.push({ memberId: 7, memberName: 'm7', block: '30-31', blockLabel: '?', loadoutSlot: 1, hourIdx: 0, dmgB: 1 });
        assert.ok(!dp.sameNotices({ plan: odd, blocks, fromIdx: 0 }).some(n => n.memberId === 7), 'ブロックの分からない凸の人に送る');
        assert.deepEqual(dp.sameNotices({ plan: null, blocks }), []);
        // 決定の通知と同じ 1 行の言い方 (lineText を共有・書式を 2 か所に書かない)
        const first = dp.notices({ prevPlan: null, nextPlan: prev, blocks, ptName: pt }).notices.find(n => n.memberId === 1);
        assert.deepEqual(first.lines, m1.lines);
    });
    test('★ previousChanged (2026-11-02 レビュー): メンバーの「前回から変わったか」は 中身の違う 1 つ前の決定と比べる — 変更なしの決定し直し (同じ中身の行) は飛ばす', () => {
        const p0 = dp.build({ blocks, ov, newIdxs: [0, 1], bosses, at: 'T0' });
        // p1: 朝の B2 を 3 → 4 に替えた (中身が違う)
        const ov1 = [{ ...ov[0], rows: [ov[0].rows[0], { ...ov[0].rows[1], pieces: [piece(4, 10, 2)] }] }, ov[1]];
        const p1 = dp.build({ blocks, ov: ov1, newIdxs: [0], prevPlan: p0, bosses, at: 'T1' });
        const p2 = dp.build({ blocks, ov: [], newIdxs: [], prevPlan: p1, bosses, at: 'T2' });   // 変更なし
        const p3 = dp.build({ blocks, ov: [], newIdxs: [], prevPlan: p2, bosses, at: 'T3' });   // もう一度 変更なし
        const row = (id, plan, season_id = 40) => ({ id, season_id, plan });
        const legacy = { id: 13, season_id: 40, plan: { levels: [] } };   // 従来の配信 (決定ではない) は比べる相手にしない
        const rows = [row(10, p0), row(11, p1), row(12, p2), legacy, row(14, p3)];
        assert.equal(dp.contentSig(p2), dp.contentSig(p1), '変更なしの行の中身が違う');
        assert.notEqual(dp.contentSig(p1), dp.contentSig(p0));
        assert.equal(dp.contentSig(dp.build({ blocks, ov: [], newIdxs: [], prevPlan: p1, bosses, at: 'ZZ' })), dp.contentSig(p1), '決定の時刻で指紋が変わる');
        assert.equal(dp.previousChanged(rows, row(14, p3))?.id, 10, '変更なしを 2 回重ねたあと、中身の違う決定まで戻らない');
        assert.equal(dp.previousChanged(rows, row(12, p2))?.id, 10);
        assert.equal(dp.previousChanged(rows, row(11, p1))?.id, 10, '普通の決定し直しは 1 つ前と比べる');
        assert.equal(dp.previousChanged(rows, row(10, p0)), null, '最初の決定に比べる相手がある');
        assert.equal(dp.previousChanged([row(10, p0), row(11, dp.build({ blocks, ov: [], newIdxs: [], prevPlan: p0, bosses }))], row(11, dp.build({ blocks, ov: [], newIdxs: [], prevPlan: p0, bosses }))), null, '中身の同じ行しか無いのに比べる相手を返す');
        assert.equal(dp.previousChanged(rows, legacy), null, '決定でない行に比べる相手を返す');
        // 人の割当が同じでも、決めたブロックが増えたら違う中身
        const p4 = dp.build({ blocks, ov: [...ov1, { idx: 2, past: false, level: 1, rows: [{ bossNumber: 4, name: 'ボス4', weakness: 'iron', pieces: [piece(9, 5, 8)] }] }], newIdxs: [2], prevPlan: p1, bosses });
        assert.notEqual(dp.contentSig(p4), dp.contentSig(p1));
        // 割当は同じで、決めたブロックだけ増えた (午後を凸 0 で決めた = メンバーには「まだ決まっていません」→「決まった」) も違う中身
        const p5 = dp.build({ blocks, ov: [{ idx: 2, past: false, level: 1, rows: [] }], newIdxs: [2], prevPlan: p1, bosses });
        assert.deepEqual(p5.decided.blocks.map(b => b.key), ['5-8', '9-12', '13-16']);
        assert.notEqual(dp.contentSig(p5), dp.contentSig(p1), '決めたブロックの違いを見ていない');
    });
    test('★ carrySkipKeys (2026-11-02 レビュー): 「凸していない」の印を新しい決定へ写す鍵 — 前の決定の id で始まり、写したブロックの終わりの時刻の印だけ', () => {
        const ac = globalThis.attackCheckDomain;
        const refs = new Set(['10|1|1|3|3|1', '10|2|1|2|3|2', '10|3|1|4|7|1', '9|1|1|3|3|1', '10|4||5||1', 'こわれた', '10|5|1|1|3']);
        // 朝 (終わり 3) は写した・午前 (終わり 7) は組み直した
        assert.deepEqual(ac.carrySkipKeys(refs, 10, 11, new Set([3])), ['11|1|1|3|3|1', '11|2|1|2|3|2']);
        assert.deepEqual(ac.carrySkipKeys(refs, 10, 11, [3, 7]).length, 3, '写したブロックの印を落とした');
        assert.deepEqual(ac.carrySkipKeys(refs, 10, 11, new Set()), [], '写したブロックが無いのに写した');
        assert.deepEqual(ac.carrySkipKeys(refs, 10, 10, new Set([3])), [], '同じ id へ写した');
        assert.deepEqual(ac.carrySkipKeys(refs, null, 11, new Set([3])), []);
        assert.deepEqual(ac.carrySkipKeys(null, 10, 11, new Set([3])), []);
        // 写した鍵は buildRows が新しい決定の id で作る鍵と同じ形 (missingKey)
        assert.equal(ac.carrySkipKeys(['10|1|1|3|3|1'], 10, 11, [3])[0], ac.missingKey(11, { memberId: 1, level: 1, bossNumber: 3, hourIdx: 3, loadoutSlot: 1 }));
    });
    test('★ rangeToDecide: いまのブロックから組めたブロックが続くところまで (途中で止める)', () => {
        const built = (s) => (i) => s.includes(i);
        assert.deepEqual(dp.rangeToDecide({ first: 1, count: 6, built: built([1, 2, 4]) }), [1, 2]);
        assert.deepEqual(dp.rangeToDecide({ first: 0, count: 6, built: built([1, 2]) }), []);
        assert.deepEqual(dp.rangeToDecide({ first: 4, count: 6, built: built([4, 5]) }), [4, 5]);
        // 空のブロックは飛ばす (朝を空けて夜に温存: 2026-10-31 ふるり)。組み直しが要るブロック (built でも skip でもない) の先は決めない
        const skip = (l) => (i) => l.includes(i);
        assert.deepEqual(dp.rangeToDecide({ first: 0, count: 6, built: built([1, 4]), skip: skip([0, 2, 3, 5]) }), [1, 4], '空のブロックを飛ばせない');
        assert.deepEqual(dp.rangeToDecide({ first: 0, count: 6, built: built([1, 4]), skip: skip([0, 2]) }), [1], '組み直しが要るブロックの先まで決める');
        assert.deepEqual(dp.rangeToDecide({ first: 0, count: 3, built: built([]), skip: skip([0, 1, 2]) }), [], '全部空なら何も決めない');
    });
    test('★ latestDecided / currentDecided: 最新の決定の行 / 最新の行が決定のときだけ', () => {
        const d = { id: 5, plan: { decided: { blocks: [{ key: '5-8' }] } } }, old = { id: 3, plan: { decided: { blocks: [{ key: '5-8' }] } } }, blk = { id: 6, plan: { blockScope: { from: 5, to: 8 } } };
        assert.equal(dp.latestDecided([old, blk, d]).id, 5);
        assert.equal(dp.currentDecided([old, d]).id, 5);
        assert.equal(dp.currentDecided([old, blk, d]), null, '後の従来の配信を無視した');
        assert.equal(dp.latestDecided([blk]), null);
    });
    test('★ timetable: 決まったブロックは全員の行 (自分は mine・✓ は planKey)・決まっていないブロックは空・いまのブロックの印', () => {
        const p = dp.build({ blocks, ov, newIdxs: [0, 1], bosses });
        const k = dp.planKey({ block: '5-8', level: 1, bossNumber: 1, memberId: 1, loadoutSlot: 1 });
        const t = dp.timetable({ blocks, plan: p, viewerId: 1, nowIdx: 1, done: new Set([k]) });
        assert.equal(t.length, blocks.length);
        assert.deepEqual(t.map(r => [r.decided, r.state]), [[true, 'past'], [true, 'now'], [false, 'later'], [false, 'later'], [false, 'later'], [false, 'later']]);
        assert.deepEqual(t[0].entries.map(e => [e.bossNumber, e.memberId, e.mine, e.done]), [[1, 2, false, false], [1, 1, true, true], [2, 3, false, false]], 'レベル → ボス → 時刻の順');
        assert.equal(t[0].entries[0].memberName, 'm2'); assert.equal(t[1].mine.length, 1); assert.equal(t[1].mine[0].loadoutSlot, 2);
        assert.equal(k, '5-8|L1|B1|1|S1');
    });
    test('★ notices: 初めて = 決まりました / 増えただけ = 決まりました / 前のブロックが変わった = 変わりました (✅ で文を分ける) / 外れた / 変わらない人には送らない', () => {
        const pt = (w) => ({ fire: '火', water: '水', wind: '風', iron: '鉄', electric: '電' })[w];
        const first = dp.build({ blocks, ov: [ov[0]], newIdxs: [0], bosses });
        const n0 = dp.notices({ prevPlan: null, nextPlan: first, blocks, ptName: pt });
        assert.deepEqual(n0.notices.map(n => [n.memberId, n.changed, n.title]), [[1, false, '🧱 あなたの凸が決まりました'], [2, false, '🧱 あなたの凸が決まりました'], [3, false, '🧱 あなたの凸が決まりました']]);
        assert.equal(n0.notices[0].lines[0], `${blocks[0].label} Lv1 B1 火PT 編成①`, '通知の行にレベルが無い (レベルだけ変わった人に本文が同じ「変わりました」になる: S4 レビュー [2])');
        // 午前を足す: 1 は増えただけ (決まりました)・2 と 3 は変わらない (送らない)
        const both = dp.build({ blocks, ov, newIdxs: [0, 1], bosses });
        const n1 = dp.notices({ prevPlan: first, nextPlan: both, blocks, ackedIds: new Set([1]) });
        assert.deepEqual(n1.notices.map(n => [n.memberId, n.changed, n.lines.length]), [[1, false, 2]]);
        assert.deepEqual(n1.unchanged, [2, 3]);
        // 朝を組み直す: 2 は B1 → B2 (変わった・✅ 済み)・3 は外れる・4 が新しく入る
        const ov2 = [{ idx: 0, past: false, level: 1, rows: [{ bossNumber: 1, pieces: [piece(1, 30, 1)] }, { bossNumber: 2, pieces: [piece(2, 20, 0), piece(4, 5, 3)] }] }, ov[1]];
        const re = dp.build({ blocks, ov: ov2, newIdxs: [0, 1], bosses });
        const n2 = dp.notices({ prevPlan: both, nextPlan: re, blocks, ackedIds: new Set([2]) });
        const by = new Map(n2.notices.map(n => [n.memberId, n]));
        assert.equal(by.get(2).title, '🔄 あなたの凸が変わりました'); assert.match(by.get(2).body, /✅ 確認したあとに/);
        assert.equal(by.get(3).gone, true); assert.match(by.get(3).body, /まだ確認していませんが/);
        assert.equal(by.get(4).title, '🧱 あなたの凸が決まりました');
        assert.ok(!by.has(1)); assert.deepEqual(n2.unchanged, [1]);
        // 編成のキャラが変わった人も「変わりました」
        const ov3 = [{ ...ov2[0], rows: [{ bossNumber: 1, pieces: [piece(1, 30, 1, { team: ['x'] })] }, ov2[0].rows[1]] }, ov[1]];
        assert.deepEqual(dp.notices({ prevPlan: re, nextPlan: dp.build({ blocks, ov: ov3, newIdxs: [0, 1], bosses }), blocks }).notices.map(n => [n.memberId, n.changed]), [[1, true]]);
    });
    test('★ S4 引き継ぎ 1: 決定し直しても済んだ凸は残す — ✓ は planKey・数字の報告は 人|レベル|ボス の数・自動の結果に同じ凸があれば足さない・済んでいない凸は残さない', () => {
        const prev = dp.build({ blocks, ov, newIdxs: [0, 1], bosses });
        // 朝 (いま) を組み直した: 2 は ✓ 済み (B1)・1 は数字で報告済み (Lv1 B1)・3 はまだ → 自動の結果は まだの凸 (3) と新しい 6 だけ
        const ovRe = [{ idx: 0, past: false, level: 1, rows: [{ bossNumber: 2, name: 'ボス2', weakness: 'water', pieces: [piece(3, 10, 2), piece(6, 12, 1)] }] }, ov[1]];
        const k2 = dp.planKey({ block: '5-8', level: 1, bossNumber: 1, memberId: 2, loadoutSlot: 1 });
        const next = dp.build({ blocks, ov: ovRe, newIdxs: [0, 1], prevPlan: prev, bosses, done: { keys: new Set([k2]), loose: new Map([['1|1|1', 1]]) } });
        assert.deepEqual(dp.flat(next).filter(a => a.block === '5-8').map(a => [a.memberId, a.bossNumber]).sort(), [[1, 1], [2, 1], [3, 2], [6, 2]], '済んだ凸が決定から消えた / 余計な凸が入った');
        assert.equal(next.decided.blocks[0].attacks, 4);
        const nn = dp.notices({ prevPlan: prev, nextPlan: next, blocks });
        assert.deepEqual(nn.notices.map(x => x.memberId), [6], '済んだ凸の人に「変わりました / 外れました」が飛ぶ');
        // 済んでいない凸は残さない (組み直しで外した凸は外れる)
        const none = dp.build({ blocks, ov: ovRe, newIdxs: [0, 1], prevPlan: prev, bosses, done: { keys: new Set(), loose: new Map() } });
        assert.deepEqual(dp.flat(none).filter(a => a.block === '5-8').map(a => a.memberId).sort(), [3, 6]);
        // 自動の結果に同じ凸があれば足さない (二重にしない)
        const ovDup = [{ idx: 0, past: false, level: 1, rows: [{ bossNumber: 1, name: 'ボス1', weakness: 'fire', pieces: [piece(2, 20, 0)] }] }, ov[1]];
        assert.equal(dp.flat(dp.build({ blocks, ov: ovDup, newIdxs: [0, 1], prevPlan: prev, bosses, done: { keys: [k2], loose: {} } })).filter(a => a.block === '5-8' && a.memberId === 2).length, 1, '同じ凸を二重にした');
        // 数字の報告はブロックの順に消し込む: 9 は朝と午前に B5 (Lv1)。報告 1 つ = 朝のぶん → 組み直した午前には残さない / 報告 2 つなら午前にも残す
        const ovA = [{ idx: 0, past: false, level: 1, rows: [{ bossNumber: 5, name: 'ボス5', weakness: 'electric', pieces: [piece(9, 50, 1)] }] }, { idx: 1, past: false, level: 1, rows: [{ bossNumber: 5, name: 'ボス5', weakness: 'electric', pieces: [piece(9, 40, 5, { loadoutSlot: 2 })] }] }];
        const prevA = dp.build({ blocks, ov: ovA, newIdxs: [0, 1], bosses });
        const reA = (n) => dp.build({ blocks, ov: [{ idx: 0, past: true, level: null, rows: [] }, { idx: 1, past: false, level: 1, rows: [] }], newIdxs: [1], prevPlan: prevA, bosses, done: { keys: [], loose: { '9|1|5': n } } });
        assert.equal(dp.flat(reA(1)).filter(a => a.block === '9-12').length, 0, '前のブロックのぶんの報告で、後のブロックの凸を済みにした');
        assert.equal(dp.flat(reA(2)).filter(a => a.block === '9-12').length, 1);
        assert.equal(dp.flat(reA(1)).filter(a => a.block === '5-8').length, 1, '過ぎたブロックは前の決定のまま');
        // ✓ の鍵を先に見る: 9 の午前が ✓・報告 1 つ = 朝のぶん → 両方残る
        const kA = dp.planKey({ block: '9-12', level: 1, bossNumber: 5, memberId: 9, loadoutSlot: 2 });
        const both = dp.build({ blocks, ov: [{ idx: 0, past: false, level: 1, rows: [] }, { idx: 1, past: false, level: 1, rows: [] }], newIdxs: [0, 1], prevPlan: prevA, bosses, done: { keys: [kA], loose: { '9|1|5': 1 } } });
        assert.deepEqual(dp.flat(both).map(a => a.block).sort(), ['5-8', '9-12']);
        assert.deepEqual([...dp.doneInPrev(blocks, dp.decidedBlocks(prevA), prevA, null)], [], 'done が無ければ空');
    });
    test('★ S4 引き継ぎ 3: 決定の各ブロックに組んだときの指紋 (fp) を残す・決め直さないブロックは前の fp を写す / 引き継ぎ 2: 時間割のレベルは 1〜4 の数だけ・壊れた行で落ちない / 引き継ぎ 11: 並び順だけでは変わらない', () => {
        const p = dp.build({ blocks, ov, newIdxs: [0, 1], bosses, fpOf: (i) => 'fp' + i });
        assert.deepEqual(p.decided.blocks.map(b => b.fp), ['fp0', 'fp1']);
        const q = dp.build({ blocks, ov: [{ idx: 0, past: true, level: null, rows: [] }, ov[1]], newIdxs: [1], prevPlan: p, bosses, fpOf: (i) => 'new' + i });
        assert.deepEqual(q.decided.blocks.map(b => [b.key, b.kept, b.fp]), [['5-8', true, 'fp0'], ['9-12', false, 'new1']]);
        assert.ok(!('fp' in dp.build({ blocks, ov, newIdxs: [0], bosses }).decided.blocks[0]), 'fpOf が無いのに fp を入れた');
        assert.ok(!('fp' in dp.build({ blocks, ov, newIdxs: [0], bosses, fpOf: () => ({ x: 1 }) }).decided.blocks[0]), '文字でない fp を入れた');
        // 時間割のレベル: 配信の行は anon で書ける → 文字・範囲外は null
        const bad = { levels: [], decided: { blocks: [{ key: '5-8', level: '<img src=x onerror=alert(1)>' }, { key: '9-12', level: '3' }, { key: '13-16', level: 9 }] } };
        const t = dp.timetable({ blocks, plan: bad, nowIdx: 0 });
        assert.deepEqual(t.slice(0, 3).map(r => [r.decided, r.level]), [[true, null], [true, 3], [true, null]]);
        assert.deepEqual([...dp.decidedBlocks(bad).keys()], ['5-8', '9-12', '13-16']);
        // 壊れた行 (blocks に null・levels が配列でない) は決定として読まない (画面が落ちる: S4 レビュー [7][13])
        // ブロックが 1 つも無い / 鍵が 'from-to' でない行も決定として読まない (S4 Codex 監査 E)
        for (const broken of [{ levels: [], decided: { blocks: [null, { key: '5-8' }] } }, { levels: {}, decided: { blocks: [{ key: '5-8' }] } }, { levels: [], decided: { blocks: [5] } },
            { levels: [], decided: { blocks: [] } }, { levels: [], decided: { blocks: [{}] } }, { levels: [], decided: { blocks: [{ key: '<b>x</b>' }] } }, { levels: [], decided: { blocks: [{ key: ['5-8'] }] } }]) {
            assert.equal(dp.isDecided(broken), false, JSON.stringify(broken));
            assert.equal(dp.latestDecided([{ id: 9, plan: broken }]), null);
            assert.equal(dp.decidedBlocks(broken).size, 0);
        }
        // flat / attacksIn は null のレベル・ボスで落ちない
        const holes = { levels: [null, { level: 1, bosses: [null, { bossNumber: 1, attacks: [null, { memberId: 1, hourIdx: 0, dmgB: 3 }] }] }], decided: { blocks: [{ key: '5-8' }] } };
        assert.deepEqual(dp.flat(holes).map(a => a.memberId), [1]);
        assert.deepEqual(globalThis.planChainDomain.attacksIn(holes, blocks[0]).map(a => a.memberId), [1]);
        // 並び順: 同じ人が同じブロック・同じボスに 2 凸 (編成①・②)。並びが逆でも「変わらない」
        const two = (order) => dp.build({ blocks, ov: [{ idx: 0, past: false, level: 1, rows: [{ bossNumber: 1, name: 'ボス1', weakness: 'fire', pieces: order.map(sl => piece(1, 10 + sl, 1, { loadoutSlot: sl, team: ['t' + sl] })) }] }], newIdxs: [0], bosses });
        const nt = dp.notices({ prevPlan: two([1, 2]), nextPlan: two([2, 1]), blocks });
        assert.deepEqual(nt.notices, [], '並び順だけで「変わりました」');
        assert.deepEqual(nt.unchanged, [1]);
    });
    test('★ S4 レビュー [10]: Lv4 (ボス 5) の凸は、数字の報告の Lv3 の鍵 (DB の level が 3) でも消し込む — Lv4 の鍵が先', () => {
        assert.deepEqual(dp.looseKeysOf({ memberId: 7, level: 4, bossNumber: 5 }), ['7|4|5', '7|3|5']);
        assert.deepEqual(dp.looseKeysOf({ memberId: 7, level: 3, bossNumber: 5 }), ['7|3|5']);
        assert.deepEqual(dp.looseKeysOf({ memberId: 7, level: 4, bossNumber: 1 }), ['7|4|1']);
        const ov4 = [{ idx: 0, past: false, level: 4, rows: [{ bossNumber: 5, name: 'ボス5', weakness: 'electric', infinite: true, pieces: [piece(7, 30, 1)] }] }];
        const prev4 = dp.build({ blocks, ov: ov4, newIdxs: [0], bosses });
        const kept = dp.doneInPrev(blocks, dp.decidedBlocks(prev4), prev4, { keys: [], loose: { '7|3|5': 1 } });
        assert.equal((kept.get('5-8') || []).length, 1, 'Lv4 の凸を Lv3 の報告で消し込んでいない');
    });
}

console.log('\n🧱 Lv4 の盤面 (S4 レビュー [1]):');
{
    const pc = globalThis.planChainDomain, bb = globalThis.blockBuildDomain, rbx = globalThis.raidBlocksDomain;
    const blocks = rbx.normalize(rbx.DEFAULT_BLOCKS).blocks;
    const W = ['iron', 'electric', 'fire', 'wind', 'water'];
    const deadBoard = (lv = 3, remRaw = 0) => ({ season: { current_level: lv, hard_date: '2026-10-31' }, bosses: W.map((w, i) => ({ boss_number: i + 1, weakness: w, tier: 'lord', name: `B${i + 1}`, total_hp_raw: 50e9, remaining_hp_raw: remRaw })),
        players: [{ id: 1, name: 'あ', attackCount: 0, attacks: [] }, { id: 2, name: 'い', attackCount: 0, attacks: [] }] });
    test('★ liveBoard: Lv3 を倒した盤面 (current_level 3 + 5 体とも 0) を Lv4 (ボス 5 だけ・HP 無限) として読む / ほかはそのまま', () => {
        const lv4 = pc.liveBoard(deadBoard());
        assert.equal(lv4.season.current_level, 4);
        assert.deepEqual(lv4.bosses.map(b => b.remaining_hp_raw), [0, 0, 0, 0, 1e15]);
        const alive = deadBoard(3, 1e9); assert.equal(pc.liveBoard(alive), alive, '生きているボスがいるのに Lv4 にした');
        const lv2 = deadBoard(2); assert.equal(pc.liveBoard(lv2), lv2, 'Lv1・2 は DB が上げる (ここでは触らない)');
        const four = { ...deadBoard(), bosses: deadBoard().bosses.slice(0, 4) }; assert.equal(pc.liveBoard(four), four, '5 体そろっていないのに Lv4 にした');
    });
    test('★ projectBoard / overview: Lv4 の盤面ではボス 5 の凸を実行する (前は全部「実行されない」になり、決定し直すと Lv4 の割当が消えた)', () => {
        const plan = { levels: [{ level: 4, infinite: true, bosses: [{ bossNumber: 5, attacks: [{ memberId: 1, hourIdx: 13, dmgB: 30, team: ['x'], loadoutSlot: 1 }, { memberId: 2, hourIdx: 14, dmgB: 20, team: ['y'], loadoutSlot: 1 }] }] }] };
        const proj = pc.projectBoard(deadBoard(), plan, blocks[3], { levelLockInBlock: true });
        assert.deepEqual(proj.done.map(d => [d.memberId, d.bossNumber]), [[1, 5], [2, 5]], 'Lv4 の凸を実行していない');
        assert.equal(proj.level, 4);
        const ov = bb.overview({ board: deadBoard(), blocks, first: 3, planOf: (i) => (i === 3 ? plan : null), hpOf: () => 0 });
        assert.equal(ov[3].level, 4);
        assert.deepEqual(ov[3].rows.map(r => [r.bossNumber, r.infinite, r.pieces.length]), [[5, true, 2]], 'Lv4 のボス 5 の行と置いた凸が出ない');
        assert.deepEqual(ov[3].skipped, []);
        assert.equal(ov[4].level, 4, '次のブロックも Lv4');
    });
    test('★ blockBuild.inBlockOf: ✓ の行 (plan_key あり) は鍵のブロックで決める (押した時刻ではない)・それ以外は報告の時刻 (S4 レビュー [11][17])', () => {
        assert.equal(bb.inBlockOf({ plan_key: '5-8|L1|B3|7|S1', reported_at: '2026-10-31T08:30:00Z' }, blocks[0]), true, '朝の ✓ を夕方に押したら朝にならない');
        assert.equal(bb.inBlockOf({ plan_key: '5-8|L1|B3|7|S1', reported_at: '2026-10-31T08:30:00Z' }, blocks[3]), false, '夕方に押した朝の ✓ を夕方に数えた');
        assert.equal(bb.inBlockOf({ reported_at: '2026-10-31T08:30:00Z' }, blocks[3]), true, '数字の報告は報告の時刻 (17:30 JST = 夕方)');
    });
    test('★ S4 レビュー [16] publishedPlans: 決定の行は決めたブロックにだけ効く (1 日ぶんとして全部のブロックに効かせない)', () => {
        const pd = globalThis.publishedPlansDomain;
        const dec = { id: 10, plan: { levels: [], decided: { blocks: [{ key: '5-8' }] } } }, eve = { id: 11, plan: { blockScope: { from: 17, to: 20 } } };
        assert.deepEqual(pd.byBlocks([dec, eve], blocks).map(x => [x.key, x.pub.id]), [['5-8', 10], ['17-20', 11]], '決めていない午前・夜に決定の行が効いた');
        assert.equal(pd.effectiveFor([dec, eve], '9-12'), null);
        assert.equal(pd.previousFor([dec, { id: 12, plan: { blockScope: { from: 5, to: 8 } } }], { id: 12, plan: { blockScope: { from: 5, to: 8 } } }, '5-8').id, 10);
        assert.equal(pd.previousFor([dec, { id: 12, plan: { blockScope: { from: 9, to: 12 } } }], { id: 12, plan: { blockScope: { from: 9, to: 12 } } }, '9-12'), null, '午前の 1 つ前に、朝だけの決定を数えた');
        const all = { id: 9, plan: { levels: [] } };
        assert.equal(pd.effectiveFor([all, dec], '9-12').id, 9, '1 日ぶんの行は従来どおりどのブロックにも効く');
    });
    test('★ S4 レビュー [19][21] attackCheck: 決定の割当 (blockEnd) と ✓ の行には「予定の時刻とずれ」を付けない', () => {
        const ac = globalThis.attackCheckDomain;
        const plan = { levels: [{ level: 1, bosses: [{ bossNumber: 1, attacks: [{ memberId: 1, dmgB: 30, hourIdx: 3, blockEnd: true }] }] }] };
        const rowsOf = (a) => { const out = ac.buildRows({ attacks: [{ id: 1, player_id: 1, boss_number: 1, level: 1, reported_at: '2026-10-30T20:10:00Z', damage_raw: 25e9, ...a }], plan, nowMs: Date.parse('2026-10-31T00:00:00Z') }); return (out.rows || out)[0].flags.map(f => f.key); };
        assert.ok(!rowsOf({}).includes('time'), '決定の割当に時刻のずれを付けた (5 時の数字の報告・割当は朝の終わり 8 時)');
        const plan2 = { levels: [{ level: 1, bosses: [{ bossNumber: 1, attacks: [{ memberId: 1, dmgB: 30, hourIdx: 0 }] }] }] };
        const flags2 = (a) => { const out = ac.buildRows({ attacks: [{ id: 1, player_id: 1, boss_number: 1, level: 1, reported_at: '2026-10-30T23:20:00Z', ...a }], plan: plan2, nowMs: Date.parse('2026-10-31T00:00:00Z') }); return (out.rows || out)[0].flags.map(f => f.key); };
        assert.ok(!flags2({ damage_raw: 0, source: 'tap' }).includes('time'), '✓ の行 (押した時刻) に時刻のずれを付けた');
        assert.ok(flags2({ damage_raw: 30e9 }).includes('time'), '従来の数字の報告は時刻のずれのまま');
    });
}

