        assert.ok(/const stateNote = o\.level >= 4 \?/.test(ob) && /\(stateNote \? `<p class="ob-note">\$\{stateNote\}<\/p>` : ''\)/.test(ob), 'Lv4 / 撃破済み の状態の文まで「？」に隠している (状態は出したまま)');
