        assert.ok(/if \(_opsCurrentAttr\) renderOpsFinishList\(_opsCurrentAttr\);[^\n]*\n[^\n]*\n\s*_opsFinSync\(\);/.test(html), '盤面を描き直したときに出し入れを合わせていない');
