        assert.ok(/\(_atkTap\.blk\.idx !== L\.sel \|\| !!L\.showPast !== !!_atkTap\.showPast\)/.test(tap) && /L\.showPast = _atkTap\.showPast;/.test(tap) && /sel, showPast: _atkTap\.showPast \};/.test(tap), '取り直しの最中に「済」の 1 行を押しても描き直さない');
